import { readdirSync, writeFileSync } from 'node:fs';
for (const framework of ['vue', 'svelte']) {
  const ext = framework === 'vue' ? 'vue' : 'svelte';
  const names = readdirSync('src/' + framework)
    .filter((f) => f.endsWith('.' + ext))
    .map((f) => f.slice(0, -ext.length - 1))
    .sort();
  let source =
    '/** Public component props for typed wrappers. Generated by scripts/generate-props.mjs. */\n';
  for (const name of names)
    source +=
      `export type ${name}Props = ` +
      (framework === 'vue'
        ? `InstanceType<typeof import("./${name}.vue").default>["$props"];`
        : `import("svelte").ComponentProps<typeof import("./${name}.svelte").default>;`) +
      '\n';
  writeFileSync(`src/${framework}/component-props.ts`, source);
}
